function redactSensitiveTextWithStats(value) {
  let text = String(value ?? '');
  let redactions = 0;

  for (const { regex, replacement } of SENSITIVE_TEXT_PATTERNS) {
    text = text.replace(regex, (...args) => {
      redactions += 1;
      return typeof replacement === 'function' ? replacement(...args) : replacement;
    });
  }

  return { text, redactions };
}

export function redactSensitiveText(value) {
  return redactSensitiveTextWithStats(value).text;
}

function redactSensitiveValue(value, key = '') {
  if (value === undefined || value === null) return value;
  if (SENSITIVE_FIELD_NAME_REGEX.test(key)) return '[REDACTED_SECRET]';
  if (typeof value === 'string') return redactSensitiveText(value);
  if (Array.isArray(value)) return value.map(item => redactSensitiveValue(item));
  if (typeof value === 'object') {
    return Object.fromEntries(
      Object.entries(value).map(([entryKey, entryValue]) => [entryKey, redactSensitiveValue(entryValue, entryKey)])
    );
  }
  return value;
}

function redactContextText(value, privacyStats) {
  if (value === undefined || value === null) return null;
  const result = redactSensitiveTextWithStats(value);
  privacyStats.sensitive_values_redacted += result.redactions;
  return result.text;
}

