function getGitBranch(repoPath) {
  try {
    return execSync('git rev-parse --abbrev-ref HEAD', {
      cwd: repoPath || process.cwd(),
      encoding: 'utf-8',
      stdio: ['pipe', 'pipe', 'ignore']
    }).trim();
  } catch {
    return 'master';
  }
}

